fn less_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Create a vector to store the results
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate through both arrays simultaneously
    for i in 0..a.len() {
        // Compare a[i] and b[i], push the result
        result.push(a[i] <= b[i]);
    }
    
    result
}